/* Tidepool disclosure (Figma node 15:14). Values come from src/styles/tokens.css. */
.disclosure {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  height: 38px;
  gap: var(--gap-s);
  color: var(--text-primary);
  /* Text style "m" */
  font-family: "Inter", sans-serif;
  font-size: 14px;
  font-weight: 500;
  line-height: 20px;
}

.disclosure__trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--gap-s);
  margin: 0;
  padding: var(--padding-s);
  background: var(--surface-page);
  border: var(--stroke-default) solid var(--field-border);
  border-radius: var(--radii-field);
  color: inherit;
  font: inherit;
  text-align: start;
  cursor: pointer;
}

/* Figma has no focus state yet: this ring is ours until the design has one. */
.disclosure__trigger:focus-visible {
  outline: 2px solid var(--text-primary);
  outline-offset: 2px;
}

.disclosure__label {
  flex: 1 0 0;
  min-width: 0;
  overflow-wrap: break-word;
}

.disclosure__chevron {
  flex-shrink: 0;
  width: 12px;
  height: 12px;
  fill: none;
  stroke: currentColor;
  stroke-width: var(--stroke-default);
}

.disclosure.disclosure--expanded {
  height: 74px;
}

.disclosure--expanded .disclosure__chevron {
  transform: rotate(180deg);
}

.disclosure__panel {
  padding: var(--padding-s);
}

.disclosure__panel[hidden] {
  display: none;
}

.disclosure__content {
  margin: 0;
  overflow-wrap: break-word;
  /* Text style "s" */
  font-size: 12px;
  line-height: 16px;
}

