import { useId, useState } from "react";
import "./Disclosure.css";

/**
 * Tidepool disclosure: shows or hides a short passage under its label.
 * Props follow the Figma component: Label, Content, Expanded (Expanded is the initial state).
 */
export function Disclosure({
  Label = "Details",
  Content = "Shipping takes two business days.",
  Expanded = false,
  className,
}) {
  const [isExpanded, setIsExpanded] = useState(Expanded);
  const panelId = useId();

  return (
    <div
      className={[
        "disclosure",
        isExpanded && "disclosure--expanded",
        className,
      ]
        .filter(Boolean)
        .join(" ")}
    >
      <button
        type="button"
        className="disclosure__trigger"
        aria-expanded={isExpanded}
        aria-controls={panelId}
        onClick={() => setIsExpanded((value) => !value)}
      >
        <span className="disclosure__label">{Label}</span>
        <svg
          className="disclosure__chevron"
          viewBox="0 0 12 12"
          aria-hidden="true"
          focusable="false"
        >
          <polyline points="1,4 6,9 11,4" />
        </svg>
      </button>
      <div id={panelId} className="disclosure__panel" hidden={!isExpanded}>
        <p className="disclosure__content">{Content}</p>
      </div>
    </div>
  );
}

export default Disclosure;

