import './Field.css';

/**
 * field: a one-line text input (Figma node 3:21).
 * `state` is Figma's State variant: "Default" | "Error".
 * Figma draws no label, so the accessible name comes from `label` (aria-label)
 * or an `aria-labelledby` passed through. In the Error state, pass the id of
 * the error message as `aria-describedby`; the design does not define its words.
 */
export function Field({ state = 'Default', label, className, ...rest }) {
  const isError = state === 'Error';
  const classes = ['field', isError && 'field--error', className].filter(Boolean).join(' ');
  return (
    <input
      type="text"
      className={classes}
      aria-label={label}
      aria-invalid={isError ? 'true' : undefined}
      {...rest}
    />
  );
}

export default Field;

