import { useId, useState } from 'react';
import './Stepper.css';

// Figma: "Picks a whole number from 0 to 10 by stepping it down or up."
const MIN = 0;
const MAX = 10;

const clamp = (n) => Math.min(MAX, Math.max(MIN, n));

/**
 * stepper (Figma node 17:2).
 * Value: the current number (Figma's prop name and default, 1). Pass `onChange` to
 * control it; without it the stepper keeps its own state, starting at `Value`.
 */
export function Stepper({ Value = 1, onChange, label = 'Value', className }) {
  const [own, setOwn] = useState(() => clamp(Number(Value)));
  const controlled = onChange !== undefined;
  const current = controlled ? clamp(Number(Value)) : own;
  const valueId = useId();

  const set = (next) => {
    const n = clamp(next);
    if (n === current) return;
    if (!controlled) setOwn(n);
    onChange?.(n);
  };

  const onKeyDown = (event) => {
    const steps = { ArrowUp: current + 1, ArrowDown: current - 1, Home: MIN, End: MAX };
    if (event.key in steps) {
      event.preventDefault();
      set(steps[event.key]);
    }
  };

  return (
    <div className={className ? `stepper ${className}` : 'stepper'}>
      <button
        type="button"
        className="stepper__button"
        aria-label="Decrease"
        aria-controls={valueId}
        disabled={current <= MIN}
        onClick={() => set(current - 1)}
      >
        <svg className="stepper__icon" viewBox="0 0 12 12" aria-hidden="true">
          <rect x="1" y="5" width="10" height="2" />
        </svg>
      </button>
      <span
        id={valueId}
        className="stepper__value"
        role="spinbutton"
        tabIndex={0}
        aria-label={label}
        aria-valuenow={current}
        aria-valuemin={MIN}
        aria-valuemax={MAX}
        onKeyDown={onKeyDown}
      >
        {current}
      </span>
      <button
        type="button"
        className="stepper__button"
        aria-label="Increase"
        aria-controls={valueId}
        disabled={current >= MAX}
        onClick={() => set(current + 1)}
      >
        <svg className="stepper__icon" viewBox="0 0 12 12" aria-hidden="true">
          <rect x="1" y="5" width="10" height="2" />
          <rect x="5" y="1" width="2" height="10" />
        </svg>
      </button>
    </div>
  );
}

export default Stepper;

