import { useState } from "react";
import "./Stepper.css";

const MIN = 0;
const MAX = 10;

const clamp = (n) => Math.min(MAX, Math.max(MIN, n));

// Picks a whole number from 0 to 10 by stepping it down or up.
export function Stepper({ Value = "1", onChange, className, ...rest }) {
  const [value, setValue] = useState(() => clamp(parseInt(Value, 10) || 0));

  const step = (delta) => {
    const next = clamp(value + delta);
    if (next === value) return;
    setValue(next);
    onChange?.(String(next));
  };

  const onKeyDown = (event) => {
    const moves = { ArrowUp: 1, ArrowDown: -1, Home: MIN - value, End: MAX - value };
    if (!(event.key in moves)) return;
    event.preventDefault();
    step(moves[event.key]);
  };

  return (
    <div
      className={className ? `stepper ${className}` : "stepper"}
      role="spinbutton"
      tabIndex={0}
      aria-label="Value"
      aria-valuenow={value}
      aria-valuemin={MIN}
      aria-valuemax={MAX}
      onKeyDown={onKeyDown}
      {...rest}
    >
      <button
        type="button"
        className="stepper__decrement"
        aria-label="Decrease"
        disabled={value <= MIN}
        onClick={() => step(-1)}
      >
        <svg className="stepper__icon" viewBox="0 0 12 12" aria-hidden="true">
          <rect x="1" y="5" width="10" height="2" />
        </svg>
      </button>
      <span className="stepper__value" aria-hidden="true">
        {value}
      </span>
      <button
        type="button"
        className="stepper__increment"
        aria-label="Increase"
        disabled={value >= MAX}
        onClick={() => step(1)}
      >
        <svg className="stepper__icon" viewBox="0 0 12 12" aria-hidden="true">
          <rect x="1" y="5" width="10" height="2" />
          <rect x="5" y="1" width="2" height="10" />
        </svg>
      </button>
    </div>
  );
}

export default Stepper;

