import { useState } from "react";
import "./Stepper.css";

const MIN = 0;
const MAX = 10;

const clamp = (n) => Math.min(MAX, Math.max(MIN, n));

// Picks a whole number from 0 to 10 by stepping it down or up.
export function Stepper({ Value, defaultValue = 1, onChange, label = "Quantity", className }) {
  const [inner, setInner] = useState(clamp(Number(defaultValue)));
  const controlled = Value !== undefined;
  const current = controlled ? clamp(Number(Value)) : inner;

  const set = (next) => {
    const n = clamp(next);
    if (n === current) return;
    if (!controlled) setInner(n);
    onChange?.(n);
  };

  const onKeyDown = (e) => {
    const steps = { ArrowUp: 1, ArrowRight: 1, ArrowDown: -1, ArrowLeft: -1 };
    if (e.key in steps) set(current + steps[e.key]);
    else if (e.key === "Home") set(MIN);
    else if (e.key === "End") set(MAX);
    else return;
    e.preventDefault();
  };

  return (
    <div className={className ? `stepper ${className}` : "stepper"}>
      <button
        type="button"
        className="stepper__button"
        aria-label="Decrease"
        disabled={current <= MIN}
        onClick={() => set(current - 1)}
      >
        <span className="stepper__icon" aria-hidden="true">
          <span className="stepper__bar" />
        </span>
      </button>
      <span
        className="stepper__value"
        role="spinbutton"
        tabIndex={0}
        aria-label={label}
        aria-valuenow={current}
        aria-valuemin={MIN}
        aria-valuemax={MAX}
        onKeyDown={onKeyDown}
      >
        {current}
      </span>
      <button
        type="button"
        className="stepper__button"
        aria-label="Increase"
        disabled={current >= MAX}
        onClick={() => set(current + 1)}
      >
        <span className="stepper__icon" aria-hidden="true">
          <span className="stepper__bar" />
          <span className="stepper__bar stepper__bar--vertical" />
        </span>
      </button>
    </div>
  );
}

export default Stepper;
